export function createMkobjEnvironment(services,layout,namespace) {
    for(const[k,v]of Object.entries({pointerSize:8,longSize:8,vaListSize:8,intSize:4,charSigned:1,littleEndian:1}))
        if(layout[k]!==v)throw Error('Review changed MKOBJ ABI: '+k);
    const ptr=v=>{return CAdapter.exactAddress(v,"MKOBJ pointer exceeds exact address range",false);};
    const {env,types,memory,type,decode,kinds}=CAdapter.createScalarAdapter(services,layout,schema,ptr,{profile:"signed-enum",errors:["Review MKOBJ scalar type ","Review MKOBJ cell type ","Review MKOBJ field "]});
    env.global=name=>{const g=schema.globals.find(g=>g.name===name);if(!g)throw Error('Review MKOBJ global '+name);return env.cell(env[name],g.canonical);};
    const initialized=new Set();
    const typeSize=t=>{const a=/^(.*?)\[(\d+)\]$/.exec(t);return a?typeSize(a[1])*Number(a[2]):t.includes('*')?8:env.sizes[t]??({char:1,'signed char':1,'unsigned char':1,short:2,'unsigned short':2,int:4,'unsigned int':4,long:8,'unsigned long':8})[t];};
    const fill=(at,t,value)=>{const a=/^(.*?)\[(\d+)\]$/.exec(t);if(a){const count=Number(a[2]),step=typeSize(a[1]);if(a[1]==='char'&&typeof value==='number'){const heap=services.heap();heap.set(heap.slice(value,value+count),at);return;}for(let i=0;i<count;i++)fill(at+i*step,a[1],value?.[i]??0);return;}const record=Object.entries(schema.schema).find(([name,row])=>row.ctype===t);if(record){record[1].fields.forEach((field,i)=>{const p=env.field(at,record[0],field.name);if(field.canonical.startsWith('struct ')||field.canonical.startsWith('union ')||field.canonical.includes('['))fill(p.address,field.canonical,value?.[i]??0);else p.value=value?.[i]??0;});return;}env.cell(at,t).value=value??0;};
    schema.backings.forEach((row,i)=>{if(!row.name.includes('.')){const at=ptr(services.global(schema.globals.length+i));Object.defineProperty(env,row.name,{value:at});fill(at,row.type,namespace.initializers[row.name](env));}});
    env.staticData=(owner,name,initializer)=>{const key=owner+'.'+name,index=schema.backings.findIndex(row=>row.name===key),row=schema.backings[index];if(index<0)throw Error('Review MKOBJ local static '+key);const at=ptr(services.global(schema.globals.length+index));if(!initialized.has(key)){fill(at,row.type,initializer());initialized.add(key);}return at;};
    env.functionPointer=name=>{const fn=services.functionPointers[name];if(!fn)throw Error('Review MKOBJ function pointer '+name);return ptr(fn());};
    env.variadic=(site,...args)=>{const entry=schema.variadics[site];if(!entry||entry.site!==site)throw Error('Review MKOBJ varargs site');return services['var'+site](...args);};
    return env;
}
